// Original schematic placeholders. No licensed character artwork or permanent PIP design.
export const pipPalette=[{id:'standard',name:'Standard cream',color:'#fff1b8'},{id:'red',name:'Alex red',color:'#cf4348'},{id:'green',name:'Malik green',color:'#38864a'},{id:'pink',name:'Maya pink',color:'#d76a9d'},{id:'yellow',name:'Aiden yellow',color:'#edc74d'},{id:'white',name:'Kaito white',color:'#f2f2e8'},{id:'black',name:'Lucas black',color:'#303842'}];
export const pipGroups=[
 {id:'travel',title:'Move',icon:'🛞',parts:[{id:'hover',name:'Hover',icon:'☁️',note:'PIP floats beside me.'},{id:'wheels',name:'Rover wheels',icon:'🛞',note:'A rolling look for ground exploring.'},{id:'climber',name:'Four climbing arms',icon:'🕷️',note:'Four arms fitted. Climbing terrain comes later.'},{id:'swim',name:'Swim kit',icon:'🌊',note:'Swim gear fitted. Ocean exploring comes later.'}]},
 {id:'tool',title:'Science',icon:'🔬',parts:[{id:'scanner',name:'Scanner',icon:'📡',note:'Ask PIP about a discovery.'},{id:'lens',name:'Zoom lens',icon:'🔬',note:'Look at a discovery more closely.'},{id:'sampler',name:'Sample arm',icon:'🦾',note:'Find out what a sample can tell us.'}]},
 {id:'eyes',title:'Eyes',icon:'👀',parts:[{id:'visor',name:'Visor',icon:'▰',note:'A friendly glowing visor.'},{id:'binocular',name:'Explorer eyes',icon:'👀',note:'Two curious lenses.'},{id:'round',name:'Round eyes',icon:'◎',note:'Two round bright eyes.'}]},
 {id:'trim',title:'Fins & wings',icon:'🪽',parts:[{id:'none',name:'No extra fins',icon:'◻',note:'Keep PIP simple.'},{id:'wings',name:'Wings',icon:'🪽',note:'Little wings for a flying buddy.'},{id:'fins',name:'Fins',icon:'🐟',note:'Streamlined fins for a rover look.'}]}
];
export function standardPip(){return {color:'standard',travel:'hover',tool:'scanner',eyes:'visor',trim:'none'}}
export function normalizePip(value={}){const c=standardPip();if(pipPalette.some(x=>x.id===value?.color))c.color=value.color;for(const g of pipGroups)if(g.parts.some(p=>p.id===value?.[g.id]))c[g.id]=value[g.id];return c}
export function attachPip(config,slot,part){const next=normalizePip(config);if(slot==='color'?pipPalette.some(p=>p.id===part):pipGroups.some(g=>g.id===slot&&g.parts.some(p=>p.id===part)))next[slot]=part;return next}
export function matchPipCrew(config,index){return attachPip(config,'color',pipPalette[index+1]?.id||'standard')}
export const pipScience={
 quartz:{title:'Quartz',formula:'SiO₂',atoms:[['Si','Silicon',1],['O','Oxygen',2]],fact:'Quartz is made of silicon and oxygen. Its atoms form a repeating crystal network.',zoom:'Look for flat crystal faces. The same tiny pattern repeats through the crystal.',sample:'Quartz can let light through. Observe its shape without scratching it.',note:'One silicon for two oxygen atoms. This is a ratio in a crystal, not a separate quartz molecule.'},
 iron:{title:'Iron-bearing mineral',formula:'Fe₃O₄',atoms:[['Fe','Iron',3],['O','Oxygen',4]],fact:'Magnetite is one example of an iron-bearing mineral. It contains iron and oxygen.',zoom:'Some iron-bearing minerals, like magnetite, are attracted to a magnet.',sample:'Try comparing materials with a magnet when the magnet experiment is available.',note:'Example: magnetite. Not every iron-bearing mineral has this formula or is magnetic.'},
 fossil:{title:'Fossil',formula:'CaCO₃',atoms:[['Ca','Calcium',1],['C','Carbon',1],['O','Oxygen',3]],fact:'A fossil is a trace or remain of ancient life. It does not have one chemical formula.',zoom:'Look for shell shapes or patterns left by something that lived long ago.',sample:'Fossils can contain different minerals. Observe gently and leave the fossil safe.',note:'Example: many shells began as calcium carbonate, CaCO₃. Fossil material can change during preservation.'}
};
export function pipAnalysis(id,tool='scanner'){const item=pipScience[id];if(!item)return null;return {...item,detail:tool==='lens'?item.zoom:tool==='sampler'?item.sample:item.fact}}
export function pipSvg(config={},layer='all'){
 const c=normalizePip(config),color=pipPalette.find(p=>p.id===c.color).color;
 const shapes={
 travel:{hover:'<ellipse cx="100" cy="155" rx="38" ry="9" fill="#8adce8"/><path d="M82 171h36"/>',wheels:'<path d="M45 142h110"/><rect x="36" y="131" width="30" height="35" rx="8" fill="#29495d"/><rect x="134" y="131" width="30" height="35" rx="8" fill="#29495d"/><path stroke="#d0e4e6" d="M45 138v20m11-20v20m87-20v20m11-20v20"/>',climber:'<path fill="none" stroke-width="9" d="M64 72L35 45 18 73M136 72l29-27 17 28M62 126l-30 16-12 30M138 126l30 16 12 30"/>',swim:'<path fill="#65cbdc" d="M68 136l-32 30 40-8M132 136l32 30-40-8"/><ellipse cx="100" cy="154" rx="14" ry="17" fill="#9be8eb"/>'}[c.travel],
 trim:{none:'',wings:'<path fill="#c8edf2" d="M62 80L15 61l9 35 38 15M138 80l47-19-9 35-38 15"/>',fins:'<path fill="#65cbdc" d="M65 70L38 44l8 70M135 70l27-26-8 70"/>'}[c.trim],
 body:`<rect x="56" y="57" width="88" height="81" rx="22" fill="${color}"/><path d="M100 57V37"/><circle cx="100" cy="31" r="7" fill="#f7ca60"/><rect x="75" y="116" width="50" height="9" rx="4" fill="#a8dae3"/>`,
 eyes:{visor:'<rect x="69" y="78" width="62" height="27" rx="10" fill="#234d61"/><path stroke="#9ae9ef" stroke-width="4" d="M79 88h11m20 0h11"/>',binocular:'<path d="M87 89h26"/><rect x="61" y="73" width="35" height="34" rx="12" fill="#f7fbeb"/><rect x="104" y="73" width="35" height="34" rx="12" fill="#f7fbeb"/><circle cx="80" cy="89" r="9" fill="#3d92ad"/><circle cx="120" cy="89" r="9" fill="#3d92ad"/>',round:'<circle cx="80" cy="91" r="15" fill="#fffbed"/><circle cx="120" cy="91" r="15" fill="#fffbed"/><circle cx="80" cy="91" r="6" fill="#3d92ad"/><circle cx="120" cy="91" r="6" fill="#3d92ad"/>'}[c.eyes],
 tool:{scanner:'<path fill="#b8e6ee" d="M145 115l14-21 13 21z"/><circle cx="161" cy="89" r="8" fill="#ffd367"/>',lens:'<path stroke-width="8" d="M142 124l15-16"/><circle cx="166" cy="99" r="17" fill="#b8e6ee"/><circle cx="166" cy="99" r="7" fill="#3d92ad"/>',sampler:'<path fill="none" stroke-width="7" d="M143 115l19 12 10-13m0 0-5-14m5 14 13-7"/>'}[c.tool]};
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="200" height="200"><g stroke="#234d61" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">'+(layer==='all'?['travel','trim','body','eyes','tool'].map(k=>shapes[k]).join(''):shapes[layer]||'')+'</g></svg>';
}
